import React, { useState } from 'react';
import './ShipmentFilters.css';

const ShipmentFilters = ({ filters, onFilterChange, onSortChange, sort }) => {
  const [localFilters, setLocalFilters] = useState(filters);
  const [showFilters, setShowFilters] = useState(false);

  const handleFilterInput = (key, value) => {
    const newFilters = { ...localFilters };
    if (value) {
      newFilters[key] = value;
    } else {
      delete newFilters[key];
    }
    setLocalFilters(newFilters);
  };

  const applyFilters = () => {
    onFilterChange(localFilters);
  };

  const clearFilters = () => {
    setLocalFilters({});
    onFilterChange({});
  };

  const sortOptions = [
    { field: 'createdAt', label: 'Date Created' },
    { field: 'trackingNumber', label: 'Tracking Number' },
    { field: 'status', label: 'Status' },
    { field: 'carrier', label: 'Carrier' },
    { field: 'weight', label: 'Weight' },
  ];

  return (
    <div className="shipment-filters">
      <div className="filters-header">
        <button
          className="filter-toggle"
          onClick={() => setShowFilters(!showFilters)}
        >
          {showFilters ? '▼' : '▶'} Filters & Sort
        </button>
        <div className="sort-controls">
          <label>Sort by:</label>
          <select
            value={sort.field}
            onChange={(e) => {
              const newField = e.target.value;
              onSortChange(newField);
            }}
            className="sort-select"
          >
            {sortOptions.map((option) => (
              <option key={option.field} value={option.field}>
                {option.label}
              </option>
            ))}
          </select>
          <button
            className="sort-order-button"
            onClick={() => {
              onSortChange(sort.field);
            }}
            title={`Sort ${sort.order === 'ASC' ? 'Descending' : 'Ascending'}`}
          >
            {sort.order === 'ASC' ? '↑' : '↓'}
          </button>
        </div>
      </div>

      {showFilters && (
        <div className="filters-content">
          <div className="filter-group">
            <label>Search</label>
            <input
              type="text"
              placeholder="Search by tracking, customer, origin, destination..."
              value={localFilters.search || ''}
              onChange={(e) => handleFilterInput('search', e.target.value)}
              className="filter-input"
            />
          </div>

          <div className="filter-row">
            <div className="filter-group">
              <label>Status</label>
              <select
                value={localFilters.status || ''}
                onChange={(e) => handleFilterInput('status', e.target.value)}
                className="filter-select"
              >
                <option value="">All Statuses</option>
                <option value="PENDING">Pending</option>
                <option value="IN_TRANSIT">In Transit</option>
                <option value="DELIVERED">Delivered</option>
                <option value="CANCELLED">Cancelled</option>
              </select>
            </div>

            <div className="filter-group">
              <label>Carrier</label>
              <input
                type="text"
                placeholder="Filter by carrier..."
                value={localFilters.carrier || ''}
                onChange={(e) => handleFilterInput('carrier', e.target.value)}
                className="filter-input"
              />
            </div>

            <div className="filter-group">
              <label>Origin</label>
              <input
                type="text"
                placeholder="Filter by origin..."
                value={localFilters.origin || ''}
                onChange={(e) => handleFilterInput('origin', e.target.value)}
                className="filter-input"
              />
            </div>

            <div className="filter-group">
              <label>Destination</label>
              <input
                type="text"
                placeholder="Filter by destination..."
                value={localFilters.destination || ''}
                onChange={(e) => handleFilterInput('destination', e.target.value)}
                className="filter-input"
              />
            </div>
          </div>

          <div className="filter-actions">
            <button className="apply-button" onClick={applyFilters}>
              Apply Filters
            </button>
            <button className="clear-button" onClick={clearFilters}>
              Clear All
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ShipmentFilters;
